func (q *Queries) StudentGradable(ctx context.Context, arg StudentGradableParams) (bool, error) {
	row := q.db.QueryRow(ctx, studentGradable, arg.AllClasses, arg.UserID, arg.StudentID)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}

